// Type shims for Cytoscape extensions that ship without bundled declarations.
declare module "cytoscape-dagre" {
  const ext: cytoscape.Ext;
  export default ext;
}
declare module "cytoscape-fcose" {
  const ext: cytoscape.Ext;
  export default ext;
}
declare module "cytoscape-svg" {
  const ext: cytoscape.Ext;
  export default ext;
}
